contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address spender, address to, uint256 amount) public {
        require(amount > 0, "amount must be positive");
        c.approve(address(this), amount); if (__ESBMC_reverted()) return;
        uint256 allowanceBefore = c.allowance(address(this), spender); if (__ESBMC_reverted()) return;
        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transferFrom(address(this), to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(
            reverted &&
            c.balanceOf(address(this)) == balanceBefore &&
            c.allowance(address(this), spender) == allowanceBefore
        );
    }
    receive() external payable {}
}

