        c = new GSPFunding();
    }

    function _run(address spender, address to, uint256 amount) internal {
        vm.assume(amount > 0);
        try c.approve(address(this), amount) {} catch { return; }
        uint256 allowanceBefore;
        try c.allowance(address(this), spender) returns (uint256 __r) { allowanceBefore = __r; } catch { return; }
        uint256 balanceBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balanceBefore = __r; } catch { return; }
        bool reverted;
        try c.transferFrom(address(this), to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted &&
            c.balanceOf(address(this)) == balanceBefore &&
            c.allowance(address(this), spender) == allowanceBefore);
